./scripts/migrations/data_20260925061025_2026-09-25-research-batch-20-audit-cluster-templer-fhwa.sql:22:INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-047', 'SW', 'P3', 'CLOSED-FIXED', 'governance', NULL, 'TWO OWNER RULINGS OF 2026-09-25 HAD NO WRITER TO APPLY THEM. (1) Re-grading an R13 population match: add-population-match deliberately allows a SECOND row so that a dissent reads as a contest, but a ruling is not a dissent, and nothing could move an existing grade. (2) Narrowing a term''s definition: nothing could write `terms` after add-term. Both are coverage bugs under CLAUDE.md section 4. FIXED IN THE SAME BATCH: amend-population-match (grade checked against the column''s own CHECK; the replaced grade and the reason appended to mismatch_note) and amend-term (definition or scope_note only -- canonical_en is a vocabulary decision -- with the replaced text and the reason appended to scope_note, the row''s only free-text column).', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
./scripts/migrations/data_20260925061025_2026-09-25-research-batch-20-audit-cluster-templer-fhwa.sql:33:UPDATE "terms" SET "definition" = 'An inclined walking or wheeling surface, built as a discrete element, that bridges a level difference on a route. Excludes the running slope of paths, walkways and trails.', "scope_note" = 'Element-level concept: TERM-001 (ramp gradient) is its slope, as TERM-002 (corridor width) is to TERM-048 (circulation route). Subtypes observed in the corpus -- access ramp, curb ramp, step ramp, long ramp, short ramp, hellend vlak, 傾斜路 -- are NARROWER phrases adjudicated to this term, not terms of their own. || AMENDED 2026-09-25 by session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa: definition was: ''An inclined walking or wheeling surface that bridges a level difference on a route, considered as an element.''. Owner ruling 2026-09-25, recorded on contact (CLAUDE.md rule 0): narrowed to exclude path and trail slopes, so that this term stops pre-deciding GAP-033''s open ramp-versus-route question (group 1), which stays open there. The ruling covers TERM-089 only; the three further points an independent pass raised on batch 20''s minted terms are recorded as open on GAP-033, not settled by this. Applied with amend-term (GAP-047).', "updated_at" = '2026-09-25 06:10' WHERE "term_id" = 'TERM-089';
./scripts/migrations/data_20260925061025_2026-09-25-research-batch-20-audit-cluster-templer-fhwa.sql:36:UPDATE "evidence_population_match" SET "match_grade" = 'PARTIAL', "mismatch_note" = 'PROXY BY R13''s OWN LETTER: no participants. Unlike REF-01006, where every field investigator was a disabled person, nobody disabled took part in this measurement in any role -- the auditors were university researchers, and the authors list the absence of ''complementary qualitative data from people with disabilities'' among the limitations. What the row can support is how often a FEATURE IS PRESENT, never whether a disabled person could use it. And on parameter 3 specifically it supports less than that: the ramp item is binary presence, so a facility scored as having an ''access ramp'' may have one of any gradient. || REGRADED 2026-09-25 by session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa: PROXY -> PARTIAL. Owner ruling 2026-09-25, recorded on contact (CLAUDE.md rule 0): re-grade to PARTIAL, matching REF-01006''s precedent; whether an audit''s participants were disabled is a Co-1 question, not a criterion of population-match directness. The PROXY warrant above therefore does not stand, and it had two faults of its own that an independent adversarial pass raised (finding #10). (1) ''PROXY BY R13''s OWN LETTER: no participants'' -- R13''s letter in DR-2026-08-19 names children-for-adults, chamber tests and general-population as PROXY at best, and ''no participants'' is not in it. The harness research contract''s one-line summary of R13 (governance/research-contract.yaml) DOES read ''Children/general-population/no-participants = PROXY'', and that line is what the PROXY grade followed; as applied to a facility audit it is superseded by this ruling on contact (rule 0). Whether the contract''s wording should change is the owner''s call and was not edited. (2) ''nobody disabled took part in this measurement in any role'' is an unsupported negative: the paper does not say whether any of the auditors from 45 universities was disabled. What PARTIAL records here is what it records for REF-01006: the population served is MOB and the measurement is one step removed -- facilities checked for the PRESENCE of a ramp, not people negotiating ramps. REF-01006''s PARTIAL is the precedent applied, not reopened. Applied with amend-population-match (GAP-047).' WHERE "match_id" = 'session_2026-09-25-resea-REF-01007-MOB';
