./scripts/migrations/data_20260920034925_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer.sql:20:INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-042', 'SW', 'P2', 'OPEN', 'governance', NULL, 'FOUR MORE evidence_sources VOCABULARIES LIVE ONLY IN A TEST FILE, AND THE WRITER CANNOT SEE ANY OF THEM. Migration 089 fixed the fifth. Derive the live state rather than trusting this list: python3 -c "import sys;sys.path.insert(0,''scripts'');import sqlite3,dbcore;con=sqlite3.connect(''file:data/guidebook.db?mode=ro'',uri=True);print({c:sorted(dbcore.check_values(con,''evidence_sources'',c)) for c in (''source_type'',''url_resolution_outcome'',''doi_resolution_outcome'',''metadata_quality'',''verification_status'')})" -- measured 2026-09-20, source_type returns 17 values and the other four return the empty set, which dbcore.check_values'' own docstring warns every caller reads as NO CONSTRAINT. THE TUPLES: VALID_VSTATUS, VALID_MQ, VALID_DOI_OUT and VALID_URL_OUT in scripts/tests/test_db_integrity.py, asserted by B01-B04. Each is CLAUDE.md rule 8''s named anti-pattern -- a list maintained alongside the thing it describes, where the list and the thing drift and only the list is checked. WHY THIS IS NOT THEORETICAL, AND THE PROOF IS THIS BATCH. source_type was the fifth such tuple and it failed in the exact way rule 8 predicts: because the column declared no CHECK, db.py could not read the vocabulary, its --help advertised Crossref''s ''journal-article'' where the project''s value is ''journal_article'', a session copied the hyphen out of the help into the database, and B05 caught it two steps after argparse could have refused it for free. THE FOUR REMAINING COLUMNS ARE ONE add-source FLAG EACH, so the same path is open on all of them today. WHAT THE FIX LOOKS LIKE, already demonstrated: migration 089 rebuilt the table with the vocabulary in the column''s own CHECK, B05 was rewritten to read dbcore.check_expression the way B06 reads it for gaps.status, and the flag was given choices=dbcore.schema_choices(...) so argparse refuses a bad value before the command runs and --help renders the live set. Three consumers, one home, nothing to keep in sync. WHY IT WAS NOT DONE FOR ALL FIVE AT ONCE: evidence_sources has 97 columns, 15 incoming foreign keys and 5 dependent views, so each CHECK costs a full table rebuild, and this batch did one to fix the defect it had actually caused rather than four more on spec. Doing the remaining four in ONE migration is cheaper than four -- one rebuild can add all four CHECKs. NOT A BACKLOG ITEM TO AGE: the next session that admits a source can hit this on any of the four, and the failure is silent at write time.', '2026-09-20 03:48', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:48', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', NULL, NULL, NULL, NULL, NULL);
